import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def fetch_document_by_id(document_id: str, table_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Fetch a document/item by identifier from Amazon DynamoDB.

    Environment variables:
        AWS_REGION: AWS region name (default: us-east-1)
        DYNAMODB_TABLE_NAME: DynamoDB table name if table_name is not provided
        AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY: optional explicit credentials
    """
    if not document_id:
        raise ValueError("document_id must be a non-empty string")

    resolved_table_name = table_name or os.environ.get("DYNAMODB_TABLE_NAME")
    if not resolved_table_name:
        raise ValueError("table_name must be provided or DYNAMODB_TABLE_NAME must be set")

    region = os.environ.get("AWS_REGION", "us-east-1")

    client_kwargs = {"region_name": region}
    if os.environ.get("AWS_ACCESS_KEY_ID") and os.environ.get("AWS_SECRET_ACCESS_KEY"):
        client_kwargs.update(
            aws_access_key_id=os.environ["AWS_ACCESS_KEY_ID"],
            aws_secret_access_key=os.environ["AWS_SECRET_ACCESS_KEY"],
            aws_session_token=os.environ.get("AWS_SESSION_TOKEN"),
        )

    dynamodb = boto3.client("dynamodb", **client_kwargs)

    key = {"id": {"S": document_id}}

    try:
        response = dynamodb.get_item(
            TableName=resolved_table_name,
            Key=key,
            ConsistentRead=True,
        )
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"Failed to fetch document '{document_id}' from DynamoDB") from exc

    item = response.get("Item")
    if item is None:
        return {}

    return _deserialize_dynamodb_item(item)


def _deserialize_dynamodb_item(item: Dict[str, Any]) -> Dict[str, Any]:
    def _convert(value: Any) -> Any:
        if isinstance(value, dict):
            if "S" in value:
                return value["S"]
            if "N" in value:
                num = value["N"]
                return int(num) if num.isdigit() else float(num)
            if "BOOL" in value:
                return value["BOOL"]
            if "NULL" in value:
                return None
            if "M" in value:
                return {k: _convert(v) for k, v in value["M"].items()}
            if "L" in value:
                return [_convert(v) for v in value["L"]]
            if "SS" in value:
                return set(value["SS"])
            if "NS" in value:
                return {int(x) if x.isdigit() else float(x) for x in value["NS"]}
            if "BS" in value:
                return set(value["BS"])
        return value

    return {k: _convert(v) for k, v in item.items()}
